/** Frame 4630 -- generated by the template lab from Figma node 538:38417
 *  (Frame 4630). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- offer, lead;
 *    board copy, editable -- memorial, day-deals, cta/shop-save;
 *    photos -- photo; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const FRAME_4630_538_38417_FIGMA = {
  "offer": "538:38421", // offer: 60% OFF
  "lead": "538:38422", // lead: UP\u2028TO
  "memorial": "538:38425", // text: MEMORIAL
  "day-deals": "538:38428", // text: DAY DEALS
  "cta/shop-save": "538:38430", // text: Shop & Save
  "art/vector-741": "538:38419", // graphic: Vector 741
  "cta/cta": "538:38429", // pill: CTA
} as const;

export function Frame4630_538_38417({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [FRAME_4630_538_38417_FIGMA["offer"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/offer`} contract="lab.offer" layout={layout}
      text={asset.copy.offer || l.text!.chars} />,
    [FRAME_4630_538_38417_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [FRAME_4630_538_38417_FIGMA["memorial"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/memorial`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4630_538_38417_FIGMA["day-deals"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/day-deals`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4630_538_38417_FIGMA["cta/shop-save"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta/shop-save`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4630_538_38417_FIGMA["art/vector-741"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-741/mark`} src="/graphics/named-sale-vector-741-1bgdjnc.svg"
      fill="#F14222" layout={layout} />,
    [FRAME_4630_538_38417_FIGMA["cta/cta"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cta/cta/mark`} src="/graphics/named-sale-pill-528x120-c8636n.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
